javas.java:

int def scoreEducation(str:education) {
    if (education == "PHD") {
        return 30;
    } else if (education == "MASTER") {
        return 22;
    } else if (education == "BACHELOR") {
        return 15;
    } else {
        return 8;
    }
}


int def scoreAge(int:age) {
    if (age <= 30) {
        return 15;
    } else if (age <= 35) {
        return 12;
    } else if (age <= 40) {
        return 8;
    } else if (age <= 45) {
        return 4;
    } else {
        return 0;
    }
}


int def scoreSocialSecurity(int:months) {
    if (months >= 36) {
        return 20;
    } else if (months >= 24) {
        return 15;
    } else if (months >= 12) {
        return 10;
    } else if (months >= 6) {
        return 5;
    } else {
        return 0;
    }
}


int def scoreTalent(str:talentCategory) {
    if (talentCategory == "A") {
        return 25;
    } else if (talentCategory == "B") {
        return 18;
    } else if (talentCategory == "C") {
        return 10;
    } else {
        return 0;
    }
}


int def scoreStartup(boolean:startupRegistered, int:startupEmployees) {
    if (startupRegistered) {
        if (startupEmployees >= 10) {
            return 20;
        } else if (startupEmployees >= 5) {
            return 14;
        } else if (startupEmployees >= 1) {
            return 8;
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}


boolean def hardReject(boolean:creditViolation, boolean:criminalRecord, boolean:receivedSimilarSubsidy) {
    if (creditViolation || criminalRecord || receivedSimilarSubsidy) {
        return true;
    } else {
        return false;
    }
}


str def eligibilityStage(int:qualificationScore, boolean:hardReject, boolean:documentsComplete) {
    if (hardReject) {
        return "REJECTED";
    } else if (documentsComplete == false) {
        return "MANUAL_REVIEW";
    } else if (qualificationScore >= 75) {
        return "QUALIFIED";
    } else if (qualificationScore >= 50) {
        return "MANUAL_REVIEW";
    } else {
        return "REJECTED";
    }
}


double def educationAmount(str:education) {
    if (education == "PHD") {
        return 100000.0;
    } else if (education == "MASTER") {
        return 60000.0;
    } else if (education == "BACHELOR") {
        return 30000.0;
    } else {
        return 10000.0;
    }
}


double def talentAmount(str:talentCategory) {
    if (talentCategory == "A") {
        return 200000.0;
    } else if (talentCategory == "B") {
        return 100000.0;
    } else if (talentCategory == "C") {
        return 50000.0;
    } else {
        return 0.0;
    }
}


double def startupAmount(boolean:startupRegistered, int:startupEmployees) {
    if (startupRegistered) {
        if (startupEmployees >= 10) {
            return 100000.0;
        } else if (startupEmployees >= 5) {
            return 50000.0;
        } else if (startupEmployees >= 1) {
            return 20000.0;
        } else {
            return 0.0;
        }
    } else {
        return 0.0;
    }
}
